function build(): Record<Lang, Record<string, string>> {
  const out: Record<Lang, Record<string, string>> = { en: {}, pl: {}, de: {}, fr: {}, es: {} };
  for (const [k, en, pl, de, fr, es] of rows) {
    out.en[k] = en; out.pl[k] = pl; out.de[k] = de; out.fr[k] = fr; out.es[k] = es;
  }
  return out;
}

export const locales = build();
